var st = document.getElementById("stage");

function fit() {
  var s = Math.min(innerWidth / 1608, innerHeight / 908);
  st.style.transform = "scale(" + s + ")";
  st.style.left = (innerWidth - 1608 * s) / 2 + "px";
  st.style.top = (innerHeight - 908 * s) / 2 + "px";
}

addEventListener("resize", fit);
fit();

function go(p) {
  if (!document.getElementById(p)) p = "home";
  document.querySelectorAll(".pg").forEach(function (e) {
    e.classList.toggle("on", e.id == p);
  });
  document.querySelectorAll(".nv").forEach(function (e) {
    e.classList.toggle("on", e.dataset.go == p);
  });
  if (location.hash !== "#" + p) location.hash = p;
}

function foc() {
  setTimeout(function () {
    try {
      cm.focus({ preventScroll: true });
    } catch (x) {}
  }, 0);
}

document.addEventListener("click", function (e) {
  var b = e.target.closest("[data-go]");
  if (b) {
    if (b.dataset.sv) curSvc = b.dataset.sv;
    go(b.dataset.go);
  }
});

document.addEventListener("keydown", function (e) {
  if (e.key === "Escape") cmd();
  if (e.key === "Enter") {
    var t = e.target.closest && e.target.closest("[role=link],[role=button]");
    if (t) t.click();
  }
});

var cur = null;

function cmd() {
  md.classList.remove("on");
}

document.getElementById("pets").addEventListener("click", function (e) {
  var c = e.target.closest(".card");
  if (!c) return;
  curAd = +c.dataset.pet;
  pi = 0;
  go("adoptpet");
  return;
  cur = PT[+c.dataset.pet];
  mi.src = cur[3];
  mi.setAttribute("style", cur[8]);
  mi.alt = cur[0];
  mt.textContent = cur[0];
  ms.textContent = cur[4];
  mb.textContent = cur[5];
  ma.textContent = cur[6];
  mdc.textContent = cur[7];
  mk.textContent = "Ask about adopting " + cur[0];
  md.classList.add("on");
  mx.focus();
});

mx.onclick = cmd;

md.addEventListener("click", function (e) {
  if (e.target === md) cmd();
});

mk.onclick = function () {
  cmd();
  var t = "Hi PawCare, I'd like to ask about adopting " + cur[0] + ".";
  if (me()) {
    curConv = "adopt";
    pre = t;
    go("messages");
    return;
  }
  go("contact");
  cm.value = t;
  foc();
};

addEventListener("hashchange", function () {
  if (location.hash.slice(1) !== cpg) go(location.hash.slice(1));
});

function toast(m) {
  var t = document.getElementById("toast");
  t.textContent = m;
  t.classList.add("on");
  setTimeout(function () {
    t.classList.remove("on");
  }, 2600);
}

