A.login = async function () {
  var e = lg_e.value.trim().toLowerCase(),
    u = DB.users[e];
  if (!u || u.h !== (await hs(lg_p.value))) {
    toast("Incorrect email or password.");
    return;
  }
  DB.ses = e;
  sv();
  var p = pend || "profile";
  pend = null;
  toast("Welcome back, " + u.name.split(" ")[0] + "!");
  go(p);
};

A.signup = async function () {
  var n = su_n.value.trim(),
    e = su_e.value.trim().toLowerCase(),
    p = su_p.value;
  if (!n || !/^\S+@\S+\.\S+$/.test(e)) {
    toast("Please enter your name and a valid email.");
    return;
  }
  if (p.length < 6) {
    toast("Password must be at least 6 characters.");
    return;
  }
  if (p !== su_c.value) {
    toast("Passwords do not match.");
    return;
  }
  if (DB.users[e]) {
    toast("That email is already registered. Please log in.");
    return;
  }
  DB.users[e] = Object.assign(
    {
      name: n,
      email: e,
      h: await hs(p),
      phone: "",
      pref: "Any Pet",
      photo: "",
    },
    seed(Date.now()),
  );
  DB.ses = e;
  sv();
  toast("Account created! Welcome, " + n.split(" ")[0] + ".");
  var q = pend || "profile";
  pend = null;
  go(q);
};

A.save = function () {
  var u = me(),
    n = ep_n.value.trim(),
    e = ep_e.value.trim().toLowerCase();
  if (!n || !/^\S+@\S+\.\S+$/.test(e)) {
    toast("Please enter your name and a valid email.");
    return;
  }
  if (e !== u.email) {
    if (DB.users[e]) {
      toast("That email is already in use.");
      return;
    }
    delete DB.users[u.email];
    u.email = e;
    DB.users[e] = u;
    DB.ses = e;
  }
  u.name = n;
  u.phone = ep_p.value.trim();
  u.pref = ep_s.value;
  sv();
  toast("Profile updated.");
  go("profile");
};

