R.messages = function (u) {
  u.msgs = u.msgs || {};
  var cv =
    CONV.filter(function (c) {
      return c[0] == curConv;
    })[0] || CONV[0];
  curConv = cv[0];
  if (!u.msgs[curConv]) {
    u.msgs[curConv] = [
      {
        f: "s",
        t:
          "Hi " +
          u.name.split(" ")[0] +
          "! This is the " +
          cv[1] +
          ". How can we help you today?",
        ts: Date.now(),
      },
    ];
    sv();
  }
  var th = u.msgs[curConv],
    list = CONV.map(function (c, i) {
      var t = u.msgs[c[0]] || [],
        l = t[t.length - 1];
      return (
        '<div class="cv' +
        (c[0] == curConv ? " on" : "") +
        '" data-a="cv" data-v="' +
        c[0] +
        '" role="button" tabindex="0" style="top:' +
        (88 + i * 92) +
        'px"><span class="ci2 big">' +
        ic(c[3], 26) +
        '</span><div class="cvt"><b>' +
        E(c[1]) +
        "</b><span>" +
        E(l ? l.t : c[2]) +
        "</span></div></div>"
      );
    }).join(""),
    bub = th
      .map(function (m) {
        return (
          '<div class="mb ' +
          (m.f == "me" ? "me" : "st") +
          '"><div class="bb">' +
          E(m.t) +
          "</div><small>" +
          (m.auto ? "Automatic reply · " : "") +
          tm(m.ts) +
          "</small></div>"
        );
      })
      .join("");
  return pn(
    a(24, 26, 300, 40, "Messages", "hd") +
      list +
      a(420, 0, 1, 720, "", "dv2") +
      a(450, 16, 52, 52, ic(cv[3], 26), "ci3") +
      a(520, 16, 500, 26, E(cv[1]), "hd4") +
      a(520, 44, 600, 22, E(cv[2]), "sm") +
      a(421, 84, 1047, 1, "", "dv2") +
      '<div id="msgs" class="a scr" style="left:421px;top:85px;width:1047px;height:553px;padding:20px 28px;box-sizing:border-box">' +
      bub +
      "</div>" +
      a(421, 638, 1047, 1, "", "dv2") +
      inp("ms_t", "Type a message...", 450, 654, 840, 52) +
      bt(1312, 654, 126, 52, "Send", "send"),
    0,
  );
};

R.adoptpet = function (u) {
  var p = PT[curAd] || PT[0],
    s0 = p[8],
    al =
      s0.indexOf("scaleX") > -1
        ? s0.replace("transform:scaleX(-1)", "").replace(/^;|;$/g, "")
        : (s0 ? s0 + ";" : "") + "transform:scaleX(-1)";
  return pview({
    title: "Featured Adoptable Pet",
    back: 'go="adopt"',
    img: p[3],
    st: pi % 2 ? al : s0,
    name: p[0],
    breed: p[5],
    age: p[6],
    rows: [
      ["paw", "Species", p[4]],
      ["paw", "Breed", p[5]],
      ["cal", "Age", p[6]],
      ["user", "Status", "Available for adoption"],
    ],
    about:
      p[7] +
      " Visit the shelter or send us a message to start the adoption process.",
    b1: ["Ask About Adopting", "ask"],
    b2: [u ? "Message the Shelter" : "Contact the Shelter", "cs"],
  });
};

A.cv = function (v) {
  curConv = v;
  go("messages");
};

A.send = function () {
  var u = me(),
    t = ms_t.value.trim();
  if (!t) return;
  var k = curConv;
  u.msgs[k].push({ f: "me", t: t, ts: Date.now() });
  sv();
  go("messages");
  setTimeout(function () {
    if (me() !== u) return;
    u.msgs[k].push({
      f: "s",
      t: "Thanks for your message! Our team will reply during shelter hours (8 AM–5 PM).",
      ts: Date.now(),
      auto: 1,
    });
    sv();
    if (cpg == "messages" && curConv == k) go("messages");
  }, 1200);
};

A.ask = function () {
  var t = "Hi PawCare, I'd like to ask about adopting " + PT[curAd][0] + ".";
  if (me()) {
    curConv = "adopt";
    pre = t;
    go("messages");
    return;
  }
  go("contact");
  cm.value = t;
  foc();
};

A.cs = function () {
  go("contact");
};

A.ba = function () {
  go("adopt");
};

document.addEventListener("click", function (e) {
  var t = e.target.closest("[data-a]");
  if (t && A[t.dataset.a]) A[t.dataset.a](t.dataset.v, t);
});

gm.addEventListener("click", function (e) {
  if (e.target === gm) A.mx();
});

document.addEventListener("keydown", function (e) {
  if (e.key === "Escape") A.mx();
  if (e.key === "Enter") {
    var m = {
      lg_e: "login",
      lg_p: "login",
      su_n: "signup",
      su_e: "signup",
      su_p: "signup",
      su_c: "signup",
      ms_t: "send",
    }[e.target.id];
    if (m) A[m]();
  }
});

pf.addEventListener("change", function () {
  var f = pf.files[0],
    u = me();
  if (!f || !u) return;
  var r = new FileReader();
  r.onload = function () {
    var i = new Image();
    i.onload = function () {
      var c = document.createElement("canvas");
      c.width = c.height = 240;
      var s = Math.min(i.width, i.height);
      c.getContext("2d").drawImage(
        i,
        (i.width - s) / 2,
        (i.height - s) / 2,
        s,
        s,
        0,
        0,
        240,
        240,
      );
      u.photo = c.toDataURL("image/jpeg", 0.8);
      sv();
      go(cpg);
      toast("Photo updated.");
    };
    i.src = r.result;
  };
  r.readAsDataURL(f);
  pf.value = "";
});

go(location.hash.slice(1) || "home");
